}
#knyhead::after{content:'';position:absolute;bottom:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,var(--acc),transparent);opacity:.35}
#knysigil{width:40px;height:40px;flex-shrink:0;filter:drop-shadow(0 0 7px var(--acc))}
#knyhdtxt{flex:1;min-width:0}
