#knynm{font-family:var(--fh);font-size:15px;font-weight:700;color:#f0e8d4;letter-spacing:.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#knyrankbadge{display:inline-flex;align-items:center;gap:5px;margin-top:2px}
#knyrankbadge .rb{font-family:var(--fh);font-size:9px;padding:1px 8px;border-radius:99px;background:var(--abg);border:1px solid var(--abd);color:var(--acc);letter-spacing:.5px}
#knyhdvit{display:flex;flex-direction:column;gap:4px;min-width:130px;flex-shrink:0}
.hbar-row{display:flex;align-items:center;gap:5px}
.hbar-lbl{font-size:7.5px;font-family:var(--fh);color:var(--tx3);width:18px;text-align:right;flex-shrink:0}
.hbar-track{flex:1;height:4px;background:rgba(255,255,255,.06);border-radius:3px;overflow:hidden}
.hbar-fill{height:100%;border-radius:3px;transition:width .5s}
.hbar-hp{background:linear-gradient(90deg,#a83030,#e06060);box-shadow:0 0 5px rgba(200,70,70,.5)}
.hbar-st{background:linear-gradient(90deg,#9a6b20,#d4a030);box-shadow:0 0 5px rgba(200,140,40,.5)}
.hbar-val{font-size:7.5px;color:var(--tx3);min-width:44px;text-align:right;flex-shrink:0}
#knylnbtn{font-family:var(--fh);font-size:8px;padding:3px 8px;border-radius:99px;cursor:pointer;background:rgba(255,255,255,.04);border:1px solid var(--bd);color:var(--tx3);letter-spacing:1.5px;user-select:none;flex-shrink:0;transition:all .2s}
#knylnbtn:hover{color:var(--acc);border-color:var(--acc)}
#knychev{font-size:14px;color:var(--tx3);transition:transform .3s;flex-shrink:0}
#knywin.closed #knychev{transform:rotate(180deg)}
/* BODY */
#knybody{max-height:2200px;overflow:hidden;transition:max-height .4s ease}
#knywin.closed #knybody{max-height:0}
/* TABS */
#knytabs{display:flex;background:var(--bg2);border-bottom:1px solid rgba(255,255,255,.05);overflow-x:auto;scrollbar-width:none}
#knytabs::-webkit-scrollbar{display:none}
.kny-tab{flex:1;padding:9px 2px;text-align:center;font-family:var(--fh);font-size:8px;letter-spacing:1px;text-transform:uppercase;color:var(--tx3);cursor:pointer;border-bottom:2px solid transparent;transition:all .2s;white-space:nowrap}
.kny-tab:hover{color:var(--tx2);background:rgba(255,255,255,.02)}
.kny-tab.active{color:var(--acc);border-bottom-color:var(--acc);background:linear-gradient(180deg,transparent,var(--abg))}
/* PANELS */
.kny-panel{display:none;padding:11px 13px}
.kny-panel.active{display:block}
#knywin ::-webkit-scrollbar{width:4px}
#knywin ::-webkit-scrollbar-thumb{background:var(--bd);border-radius:2px}
/* SECTION HEADER */
.kny-sec{display:flex;align-items:center;gap:8px;margin-bottom:10px;margin-top:4px;font-family:var(--fh);font-size:8px;letter-spacing:3px;text-transform:uppercase;color:var(--acc)}
.kny-sec::before,.kny-sec::after{content:'';flex:1;height:1px}
.kny-sec::before{background:linear-gradient(90deg,transparent,var(--abd))}
.kny-sec::after{background:linear-gradient(90deg,var(--abd),transparent)}
.kny-sec.mt{margin-top:16px}
/* INFO GRID */
.igrid{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-bottom:14px}
.icard{background:var(--bg3);border:1px solid var(--bg4);border-radius:var(--r2);padding:7px 10px;border-left:2px solid var(--abd);transition:border-left-color .2s}
.icard:hover{border-left-color:var(--acc)}
.icard.full{grid-column:1/-1}
.icard-l{font-family:var(--fh);font-size:8px;letter-spacing:1px;text-transform:uppercase;color:var(--tx3);margin-bottom:3px}
.icard-v{font-size:12px;color:var(--tx);font-weight:600}
/* VITAL BARS */
.bars{margin-bottom:14px}
.bar-row{display:flex;align-items:center;gap:9px;margin-bottom:8px}
.bar-lbl{font-family:var(--fh);font-size:8px;letter-spacing:.5px;color:var(--tx3);width:24px;text-align:right;flex-shrink:0}
.bar-wrap{flex:1;display:flex;flex-direction:column;gap:3px}
.bar-track{height:9px;background:rgba(255,255,255,.05);border-radius:5px;overflow:hidden;position:relative}
.bar-fill{height:100%;border-radius:5px;transition:width .6s}
.bar-hp{background:linear-gradient(90deg,#9a2828,#d85858,#f07878);box-shadow:0 0 8px rgba(200,60,60,.5)}
.bar-st{background:linear-gradient(90deg,#9a6b20,#d4922a,#f0b050);box-shadow:0 0 8px rgba(200,140,40,.5)}
.bar-rc{background:linear-gradient(90deg,#1e6878,#3898a8,#60c0c8);box-shadow:0 0 8px rgba(60,160,180,.4)}
.bar-nums{display:flex;justify-content:flex-end}
.bar-val{font-size:10px;color:var(--tx2);font-weight:600}
/* UNLIMITED display (demons) */
.unlimited-row{display:flex;align-items:center;gap:12px;padding:10px 12px;background:var(--bg3);border:1px solid rgba(200,56,74,.2);border-radius:var(--r2);margin-bottom:14px}
.unlimited-ico{font-family:var(--fh);font-size:32px;font-weight:900;color:#C8384A;text-shadow:0 0 15px rgba(200,56,74,.7);line-height:1}
.unlimited-lines{flex:1}
.unlimited-line{font-size:11px;color:var(--tx2);margin-bottom:4px}
.unlimited-line .hl{color:#C8384A;font-weight:700}
/* BADGES */
.badges{display:flex;flex-wrap:wrap;gap:5px;margin-bottom:12px}
.badge{padding:3px 9px;border-radius:99px;font-size:10px;background:var(--bg4);border:1px solid var(--bg5);color:var(--tx2)}
.badge.cond{border-color:rgba(200,140,40,.45);color:#e0a040;background:rgba(200,140,40,.1)}
.badge.inj{border-color:rgba(210,60,60,.45);color:#e07878;background:rgba(210,60,60,.1)}
.badge.none{color:var(--tx3);font-style:italic;border-color:transparent;background:transparent}
/* RANK TRACKER */
.rank-row{display:flex;align-items:center;gap:12px;padding:10px 12px;background:var(--bg3);border:1px solid var(--bg4);border-radius:var(--r2);margin-bottom:10px}
.rank-kanji{font-family:var(--fh);font-size:36px;font-weight:900;color:var(--acc);text-shadow:0 0 18px rgba(var(--acc-rgb),.6);line-height:1;min-width:44px;text-align:center}
.rank-info{flex:1}
.rank-fullname{font-size:12px;font-weight:700;color:var(--tx);margin-bottom:2px}
.rank-next{font-size:10px;color:var(--tx3)}
.rank-next .arr{color:var(--acc)}
.rank-steps{display:flex;gap:4px;align-items:center;margin-bottom:10px;flex-wrap:wrap}
.rank-dot{width:18px;height:18px;border-radius:50%;border:1.5px solid var(--bg5);background:var(--bg3);display:flex;align-items:center;justify-content:center;font-family:var(--fh);font-size:7px;color:var(--tx3);flex-shrink:0;transition:all .2s}
.rank-dot.done{border-color:rgba(var(--acc-rgb),.5);background:var(--abg);color:var(--acc)}
.rank-dot.current{border-color:var(--acc);background:var(--acc);color:#07090d;box-shadow:0 0 8px rgba(var(--acc-rgb),.5)}
.rank-arrow{color:var(--tx3);font-size:9px}
.rank-req-box{background:var(--bg3);border:1px solid var(--bg4);border-radius:var(--r2);padding:9px 11px;margin-bottom:4px}
.rank-req-lbl{font-family:var(--fh);font-size:8px;letter-spacing:1.5px;text-transform:uppercase;color:var(--tx3);margin-bottom:5px}
.rank-req-txt{font-size:11px;color:var(--tx2);line-height:1.55}
.kills-row{display:flex;align-items:center;gap:8px;margin-top:8px;font-size:10px;color:var(--tx3)}
.kills-num{font-family:var(--fh);font-size:16px;font-weight:700;color:var(--acc)}
/* ABILITIES */
.ab-card{background:var(--bg3);border:1px solid var(--bg4);border-radius:var(--r2);padding:11px 12px;margin-bottom:8px;display:flex;gap:12px;align-items:flex-start;border-left:3px solid transparent;transition:border-left-color .2s,background .2s}
.ab-card:hover{background:var(--bg4)}
.ab-card.r-S{border-left-color:#ffd700}
.ab-card.r-A{border-left-color:#d870c8}
.ab-card.r-B{border-left-color:#5088d8}
.ab-card.r-C{border-left-color:#50b870}
.ab-card.r-D{border-left-color:#707070}
.rnk-badge{width:30px;height:30px;border-radius:5px;display:flex;align-items:center;justify-content:center;font-family:var(--fh);font-weight:700;font-size:13px;flex-shrink:0;border:1px solid currentColor}
.rnk-S{color:#ffd700;background:rgba(255,215,0,.12);box-shadow:0 0 8px rgba(255,215,0,.2)}
.rnk-A{color:#d870c8;background:rgba(216,112,200,.12)}
.rnk-B{color:#5088d8;background:rgba(80,136,216,.12)}
.rnk-C{color:#50b870;background:rgba(80,184,112,.12)}
.rnk-D{color:#707070;background:rgba(112,112,112,.1)}
.ab-body{flex:1;min-width:0}
.ab-name{font-size:12px;font-weight:700;color:var(--tx);margin-bottom:1px;font-family:var(--fh)}
.ab-jp{font-size:9px;color:var(--tx3);margin-bottom:4px}
.ab-desc{font-size:11px;color:var(--tx2);line-height:1.5}
/* SKILL TREE */
.sp-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}
.sp-counter{background:var(--bg3);border:1px solid var(--abd);border-radius:var(--r2);padding:6px 12px;display:flex;align-items:center;gap:8px}
.sp-num{font-family:var(--fh);font-size:20px;font-weight:700;color:var(--acc)}
.sp-lbl{font-family:var(--fh);font-size:8px;letter-spacing:1px;color:var(--tx3);text-transform:uppercase}
.tct-row{display:flex;gap:5px;flex-wrap:wrap;margin-bottom:10px}
.tct{padding:4px 9px;border-radius:99px;font-size:9px;font-weight:700;cursor:pointer;border:1px solid var(--bg5);color:var(--tx3);background:var(--bg3);transition:all .15s;user-select:none}
.tct:hover{color:var(--tx2);border-color:var(--abd)}
.tct.active{color:#fff;background:rgba(var(--acc-rgb),.55);border-color:var(--acc)}
.skill-card{background:var(--bg3);border:1px solid var(--bg4);border-radius:var(--r2);padding:10px 11px;margin-bottom:7px;position:relative;transition:border-color .2s,background .2s}
.skill-card.unlocked{border-color:rgba(var(--acc-rgb),.35);background:rgba(var(--acc-rgb),.05)}
.skill-card.maxed{border-color:rgba(255,215,0,.35);background:rgba(255,215,0,.04)}
.skill-card.locked{opacity:.75}
.skill-card-top{display:flex;align-items:flex-start;gap:9px;margin-bottom:5px}
.skill-icon{width:28px;height:28px;border-radius:5px;background:var(--bg4);border:1px solid var(--bg5);display:flex;align-items:center;justify-content:center;font-size:14px;flex-shrink:0;transition:all .2s}
.skill-card.unlocked .skill-icon{background:var(--abg);border-color:rgba(var(--acc-rgb),.4)}
.skill-card.maxed .skill-icon{background:rgba(255,215,0,.1);border-color:rgba(255,215,0,.4)}
.skill-meta{flex:1;min-width:0}
.skill-name{font-size:12px;font-weight:700;color:var(--tx);margin-bottom:2px}
.skill-tags{display:flex;gap:5px;flex-wrap:wrap}
.skill-tag{font-size:8px;padding:1px 6px;border-radius:99px;font-weight:700;letter-spacing:.5px}
.tag-all{color:#9a9080;background:rgba(154,144,128,.12);border:1px solid rgba(154,144,128,.25)}
.tag-slayer{color:#8B9FCE;background:rgba(139,159,206,.12);border:1px solid rgba(139,159,206,.3)}
.tag-demon{color:#C8384A;background:rgba(200,56,74,.12);border:1px solid rgba(200,56,74,.3)}
.tag-hashira{color:#FFD700;background:rgba(255,215,0,.1);border:1px solid rgba(255,215,0,.3)}
.tag-upper{color:#d870c8;background:rgba(216,112,200,.1);border:1px solid rgba(216,112,200,.3)}
.skill-cost{font-family:var(--fh);font-size:9px;font-weight:700;color:var(--acc);white-space:nowrap}
.skill-desc{font-size:10px;color:var(--tx3);line-height:1.5;margin-bottom:7px}
.skill-footer{display:flex;align-items:center;justify-content:space-between;gap:8px}
.skill-level{font-size:9px;color:var(--tx3);font-family:var(--fh)}
.skill-level .cur{color:var(--acc);font-weight:700;font-size:11px}
.skill-btn{padding:4px 12px;border-radius:var(--r2);font-size:9px;font-weight:700;letter-spacing:.8px;text-transform:uppercase;cursor:pointer;border:none;transition:all .15s;font-family:var(--fh)}
.btn-unlock{background:rgba(var(--acc-rgb),.2);color:var(--acc);border:1px solid rgba(var(--acc-rgb),.4)}
.btn-unlock:hover{background:rgba(var(--acc-rgb),.35)}
.btn-upgrade{background:rgba(255,215,0,.12);color:#FFD700;border:1px solid rgba(255,215,0,.35)}
.btn-upgrade:hover{background:rgba(255,215,0,.22)}
.btn-maxed{background:rgba(255,215,0,.08);color:rgba(255,215,0,.5);border:1px solid rgba(255,215,0,.15);cursor:default}
.btn-locked{background:var(--bg4);color:var(--tx3);border:1px solid var(--bg5);cursor:default;opacity:.6}
/* INVENTORY */
.inv-group{margin-bottom:12px}
.inv-type-lbl{font-family:var(--fh);font-size:8px;letter-spacing:2px;text-transform:uppercase;color:var(--acc);padding:4px 0;border-bottom:1px solid var(--abd);margin-bottom:7px;opacity:.8}
.inv-item{display:flex;align-items:flex-start;gap:10px;padding:7px 10px;background:var(--bg3);border:1px solid var(--bg4);border-radius:var(--r2);margin-bottom:4px}
.inv-item:hover{background:var(--bg4)}
.inv-qty{font-family:var(--fh);font-size:11px;font-weight:700;color:var(--acc);min-width:26px;text-align:center;padding-top:1px;background:var(--abg);border-radius:3px}
.inv-info{flex:1;min-width:0}
.inv-name{font-size:12px;color:var(--tx);font-weight:600}
.inv-desc{font-size:10px;color:var(--tx3);margin-top:2px;line-height:1.4}
/* EQUIPMENT */
.eq-slot{display:flex;gap:10px;align-items:center;padding:9px 11px;background:var(--bg3);border:1px solid var(--bg4);border-radius:var(--r2);margin-bottom:6px}
.eq-slot:hover{background:var(--bg4)}
.eq-slbl{font-family:var(--fh);font-size:8px;letter-spacing:.5px;text-transform:uppercase;color:var(--tx3);width:70px;flex-shrink:0;text-align:right}
.eq-line{width:1px;height:30px;background:var(--bd);flex-shrink:0}
.eq-item{flex:1;min-width:0}
.eq-name{font-size:12px;font-weight:700;color:var(--tx)}
.eq-desc{font-size:10px;color:var(--tx3);margin-top:3px;line-height:1.4}
.eq-cond{font-family:var(--fh);font-size:8px;padding:1px 6px;border-radius:99px;font-weight:700;margin-left:6px;display:inline-block}
.c-pristine{color:#60e490;border:1px solid rgba(96,228,144,.4);background:rgba(96,228,144,.08)}
.c-good{color:#7890b8;border:1px solid rgba(120,144,184,.4);background:rgba(120,144,184,.08)}
.c-worn{color:#d8c070;border:1px solid rgba(216,192,112,.4);background:rgba(216,192,112,.08)}
.c-damaged{color:#d87830;border:1px solid rgba(216,120,48,.4);background:rgba(216,120,48,.08)}
.c-broken{color:#d84870;border:1px solid rgba(216,72,112,.4);background:rgba(216,72,112,.08)}
.eq-empty{font-size:11px;color:var(--tx3);font-style:italic}
/* FAME TRACKER */
.fame-card{background:var(--bg3);border:1px solid var(--bg4);border-radius:var(--r2);padding:10px 12px;margin-bottom:7px}
.fame-card:hover{background:var(--bg4)}
.fame-top{display:flex;align-items:center;gap:8px;margin-bottom:6px}
.fame-loc{font-size:12px;font-weight:700;color:var(--tx);flex:1;font-family:var(--fh)}
.fame-status-tag{font-size:8px;font-weight:700;padding:2px 8px;border-radius:99px;letter-spacing:.5px;white-space:nowrap}
.fame-bar-wrap{height:7px;background:rgba(255,255,255,.05);border-radius:5px;overflow:hidden;position:relative;margin-bottom:5px}
.fame-bar-center{position:absolute;top:0;left:50%;width:1px;height:100%;background:rgba(255,255,255,.15)}
.fame-bar-fill{height:100%;border-radius:5px;position:absolute;top:0}
.fame-bar-pos{background:linear-gradient(90deg,#3a9060,#60e090);box-shadow:0 0 6px rgba(80,200,120,.4);left:50%}
.fame-bar-neg{background:linear-gradient(90deg,#e04848,#9a2020);box-shadow:0 0 6px rgba(200,60,60,.4);right:50%}
.fame-meta{display:flex;align-items:center;justify-content:space-between}
.fame-note{font-size:10px;color:var(--tx3);line-height:1.4;flex:1}
.fame-val{font-family:var(--fh);font-size:12px;font-weight:700;min-width:40px;text-align:right}
/* EMPTY STATE */
.empty-state{text-align:center;padding:28px 0;color:var(--tx3);font-size:10px;letter-spacing:2px;font-family:var(--fh);text-transform:uppercase}
.empty-state::before{content:'◈';display:block;font-size:18px;margin-bottom:8px;opacity:.3}
/* FOOTER */
#knyfoot{border-top:1px solid rgba(255,255,255,.05);padding:7px 14px;font-family:var(--fh);font-size:8px;color:var(--tx3);text-align:center;letter-spacing:2px;background:var(--bg2);text-transform:uppercase;position:relative}
#knyfoot::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,var(--bd),transparent)}

/* SITUATION */
.sit-card{background:var(--bg3);border:1px solid var(--abd);border-left:3px solid var(--acc);border-radius:var(--r2);padding:9px 12px;margin-bottom:14px}
.sit-txt{font-size:11px;color:var(--tx2);line-height:1.65;font-style:italic}
/* CROW */
.crow-portrait{display:flex;align-items:center;justify-content:center;padding:14px;background:var(--bg3);border:1px solid var(--bg4);border-radius:var(--r2);margin-bottom:12px;flex-direction:column;gap:7px}
.crow-face{font-size:44px;line-height:1;filter:drop-shadow(0 0 8px rgba(var(--acc-rgb),.45));animation:crwP 3s ease-in-out infinite}
@keyframes crwP{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}
.crow-mood-nm{font-family:var(--fh);font-size:9px;letter-spacing:2px;text-transform:uppercase;color:var(--acc)}
.crow-hbar-row{display:flex;align-items:center;gap:9px;margin-bottom:7px}
.crow-hbar-lbl{font-family:var(--fh);font-size:8px;color:var(--tx3);width:50px;text-align:right;flex-shrink:0}
.crow-hbar-track{flex:1;height:7px;background:rgba(255,255,255,.05);border-radius:5px;overflow:hidden}
.crow-hbar-fill{height:100%;border-radius:5px}
.crow-hng-fill{background:linear-gradient(90deg,#c07840,#e8a060);box-shadow:0 0 6px rgba(200,130,60,.4)}
.crow-moo-fill{background:linear-gradient(90deg,#4a9080,#60c8a8);box-shadow:0 0 6px rgba(80,180,150,.4)}
.crow-hbar-val{font-size:9px;color:var(--tx3);min-width:38px;text-align:right}
/* COMPACT SKILL TREE */
