function fameStatus(v){
  v=parseFloat(v)||0;
  if(v>=80)return{k:'fame0',ef:'fameEff0',color:'#FFD700'};
  if(v>=50)return{k:'fame1',ef:'fameEff1',color:'#60E490'};
  if(v>=20)return{k:'fame2',ef:'fameEff2',color:'#7898C8'};
  if(v>=-19)return{k:'fame3',ef:'fameEff3',color:'#808080'};
  if(v>=-50)return{k:'fame4',ef:'fameEff4',color:'#D8A030'};
  if(v>=-80)return{k:'fame5',ef:'fameEff5',color:'#D06040'};
  return{k:'fame6',ef:'fameEff6',color:'#C83848'};
}

function getUnlockedSkill(id){
  var ul=d.unlockedSkills||[];
  for(var i=0;i<ul.length;i++){if(ul[i].id===id)return ul[i]}
  return null;
}

function canUseFaction(cat){
  var f=d.faction||'slayer';
  if(cat==='all')return true;
  if(cat==='slayer')return f==='slayer';
  if(cat==='demon')return f==='demon';
  if(cat==='hashira')return f==='slayer';
  if(cat==='upper_moon')return f==='demon';
  return false;
}

function sendToChat(txt){
  setTimeout(function(){
    try{
      var w=window.parent||window;
      var ta=w.document.getElementById('send_textarea')||w.document.querySelector('textarea.chat-input,#textareaAutosize,textarea');
      if(ta){
        var dd=Object.getOwnPropertyDescriptor(w.HTMLTextAreaElement.prototype,'value');
        if(dd&&dd.set)dd.set.call(ta,txt);else ta.value=txt;
        ta.dispatchEvent(new Event('input',{bubbles:true}));
        setTimeout(function(){try{var sb=w.document.getElementById('send_but');if(sb)sb.click();else ta.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',keyCode:13,bubbles:true}));}catch(e){}},150);
        return;
      }
    }catch(e){}
    try{navigator.clipboard.writeText(txt);}catch(e){}
  },300);
}

