var SLAYER_RANKS=[
  {key:'Mizunoto (癸)',k:'癸'},{key:'Mizunoe (壬)',k:'壬'},{key:'Kinoto (辛)',k:'辛'},
  {key:'Kanoe (庚)',k:'庚'},{key:'Tsuchinoto (己)',k:'己'},{key:'Tsuchinoe (戊)',k:'戊'},
  {key:'Hinoto (丁)',k:'丁'},{key:'Hinoe (丙)',k:'丙'},{key:'Kinoe (甲)',k:'甲'},
  {key:'Hashira (柱)',k:'柱'}
];
var DEMON_RANKS=[
  {key:'Newly Turned',k:'転'},{key:'Lesser Demon',k:'下位'},
  {key:'Named Demon',k:'名'},{key:'Lower Moon',k:'下弦'},
  {key:'Upper Moon',k:'上弦'},{key:'Progenitor Level',k:'始祖'}
];

function getRankIdx(faction,rank){
  var ranks=faction==='slayer'?SLAYER_RANKS:DEMON_RANKS;
