  var hpP=pct(hp.cur,hp.max);var stP=pct(st.cur,st.max);var rcP=pct(rc.cur,rc.max);

  // Info cards
  var rows=[[TH?'ชื่อ':'Name',d.name],[TH?'อายุ':'Age',d.age],[TH?'เพศ':'Gender',d.gender],[TH?'ฝ่าย':'Faction',d.faction]];
  if(faction==='slayer')rows.push([TH?'สไตล์หายใจ':'Breathing',d.breathingStyle]);
  rows.push([TH?'ฆ่าอสูร':T('kills'),d.killCount||0]);
  var gh='';
  rows.forEach(function(r,i){
    gh+='<div class="icard'+(i>=4?' full':'')+'"><div class="icard-l">'+esc(r[0])+'</div><div class="icard-v">'+esc(r[1]||'—')+'</div></div>';
  });

  // HP bar
  var barsH='<div class="bar-row"><div class="bar-lbl">'+T('hp')+'</div><div class="bar-wrap"><div class="bar-track"><div class="bar-fill bar-hp" style="width:'+hpP+'%"></div></div><div class="bar-nums"><span class="bar-val">'+esc(hp.cur)+' / '+esc(hp.max)+'</span></div></div></div>';

  // Stamina/Recovery
  var breathH='';
  if(faction==='demon'){
    breathH='<div class="kny-sec mt">'+T('breath')+'</div>'+
      '<div class="unlimited-row">'+
        '<div class="unlimited-ico">∞</div>'+
        '<div class="unlimited-lines">'+
          '<div class="unlimited-line">'+esc(T('stam'))+' — <span class="hl">'+T('unlimited')+'</span></div>'+
          '<div class="unlimited-line" style="margin-bottom:0">'+esc(T('rec'))+' — <span class="hl">'+T('unlimited')+'</span></div>'+
        '</div>'+
      '</div>';
  }else{
    barsH+='<div class="bar-row"><div class="bar-lbl">気</div><div class="bar-wrap"><div class="bar-track"><div class="bar-fill bar-st" style="width:'+stP+'%"></div></div><div class="bar-nums"><span class="bar-val">'+esc(st.cur)+' / '+esc(st.max)+'</span></div></div></div>';
    barsH+='<div class="bar-row"><div class="bar-lbl">癒</div><div class="bar-wrap"><div class="bar-track"><div class="bar-fill bar-rc" style="width:'+rcP+'%"></div></div><div class="bar-nums"><span class="bar-val">'+esc(rc.cur)+' / '+esc(rc.max)+'</span></div></div></div>';
  }

  // Rank tracker
  var rank=d.rank||'—';var nextRank=d.nextRank||'—';var rankReq=d.rankReq||'—';
  var ranks=faction==='slayer'?SLAYER_RANKS:DEMON_RANKS;
  var ridx=getRankIdx(faction,rank);
  var rKanji=ranks[ridx]?ranks[ridx].k:rank;
  var dotsH=ranks.map(function(r,i){
    var cls=i<ridx?'done':i===ridx?'current':'';
    return'<div class="rank-dot '+cls+'" title="'+r.key+'">'+r.k+'</div>';
  }).join('<span class="rank-arrow">›</span>');
  var rankH='<div class="kny-sec mt">'+T('rankSec')+'</div>'+
    '<div class="rank-row">'+
      '<div class="rank-kanji">'+esc(rKanji)+'</div>'+
      '<div class="rank-info">'+
        '<div class="rank-fullname">'+esc(rank)+'</div>'+
        '<div class="rank-next"><span class="arr">→</span> '+esc(nextRank)+'</div>'+
        '<div class="kills-row">'+
          '<span class="kills-num">'+esc(d.killCount||0)+'</span>'+
          '<span>'+T('kills')+'</span>'+
        '</div>'+
      '</div>'+
    '</div>'+
    '<div class="rank-steps">'+dotsH+'</div>'+
    '<div class="rank-req-box">'+
      '<div class="rank-req-lbl">'+T('rankReq')+'</div>'+
      '<div class="rank-req-txt">'+esc(rankReq)+'</div>'+
