  var ib='';
  if(!injs.length)ib='<span class="badge none">'+esc(T('norm'))+'</span>';
  else injs.forEach(function(c){ib+='<span class="badge inj">⚠ '+esc(c)+'</span>';});

  var sitH=d.situation?'<div class="kny-sec">'+T('scene')+'</div><div class="sit-card"><div class="sit-txt">'+esc(d.situation)+'</div></div>':'';
  return sitH+'<div class="kny-sec">'+T('char')+'</div>'+
