// ── PANEL: SKILL TREE ─────────────────────────────────────────────
function pTree(){
  var sp=d.skillPoints||0;
  var faction=d.faction||'slayer';
  var cats=[
    {k:'all',lbl:T('catAll')},{k:'all2',lbl:T('catUniv')},
    {k:'slayer',lbl:T('catSlayer')},{k:'demon',lbl:T('catDemon')},
    {k:'hashira',lbl:T('catHashira')},{k:'upper_moon',lbl:T('catUpper')}
  ];
  var filtersH=cats.map(function(c){
    var ck=c.k==='all2'?'all':c.k;
    var isActive=(tctFilter==='all'&&c.k==='all')||(tctFilter===c.k&&c.k!=='all')||(tctFilter==='all2'&&c.k==='all2');
    return'<div class="tct'+(tctFilter===c.k?' active':'')+'" data-cat="'+c.k+'">'+esc(c.lbl)+'</div>';
  }).join('');

  var visible=ST.filter(function(sk){
    if(tctFilter==='all')return true;
    if(tctFilter==='all2')return sk.cat==='all';
    return sk.cat===tctFilter;
  });

  var spH='<div class="sp-header">'+
    '<div class="sp-counter">'+
      '<div class="sp-num">'+esc(sp)+'</div>'+
      '<div class="sp-lbl">'+T('sp')+'</div>'+
    '</div>'+
    '<div style="font-size:9px;color:var(--tx3);font-family:var(--fh);text-align:right;line-height:1.5">'+
      (TH?'ฝ่าย:':'Faction:')+' <span style="color:var(--acc)">'+esc(faction)+'</span>'+
    '</div></div>';

  var miniH=visible.map(function(sk){
    var ul=getUnlockedSkill(sk.id);
    var level=ul?ul.level:0;
    var isUnlocked=level>0;
    var isMaxed=level>=sk.m;
    var factionOk=canUseFaction(sk.cat);
    var reqOk=!sk.req||getUnlockedSkill(sk.req);
    var canUnlock=!isUnlocked&&factionOk&&reqOk&&sp>=sk.c;
    var canUpgrade=isUnlocked&&!isMaxed&&factionOk&&sp>=sk.c;
    var cardCls='skill-card'+(isMaxed?' maxed':isUnlocked?' unlocked':' locked');
    var tagCls='tag-'+sk.cat.replace('_moon','');
    var tagLabels={all:'ALL',slayer:'SLAYER',demon:'DEMON',hashira:'HASHIRA',upper_moon:'UPPER'};
    var tagLabel=tagLabels[sk.cat]||sk.cat.toUpperCase();
    var desc=TH?sk.tD:sk.eD;
    var nm=TH?sk.th:sk.en;

    var levDisplay='';
    if(sk.m>1){
      levDisplay='<span class="cur">'+(isUnlocked?level:0)+'</span>/'+sk.m;
    }else if(isUnlocked){
      levDisplay='<span class="cur">✓</span>';
    }

    var btnH='';
    if(isMaxed){
      btnH='<button class="skill-btn btn-maxed" disabled>'+T('maxed')+'</button>';
    }else if(!factionOk){
      btnH='<button class="skill-btn btn-locked" disabled>'+T('factionLock')+'</button>';
    }else if(!reqOk){
      btnH='<button class="skill-btn btn-locked" disabled>'+T('locked')+'</button>';
    }else if(isUnlocked){
      var cls=canUpgrade?'btn-upgrade':'btn-locked';
      var dis=canUpgrade?'':'disabled';
      btnH='<button class="skill-btn '+cls+'" '+dis+' data-sk="'+sk.id+'">'+T('upg')+' ('+sk.c+'SP)</button>';
    }else{
      var cls2=canUnlock?'btn-unlock':'btn-locked';
      var dis2=canUnlock?'':'disabled';
      btnH='<button class="skill-btn '+cls2+'" '+dis2+' data-sk="'+sk.id+'">'+T('unlk')+' ('+sk.c+'SP)</button>';
    }

    return'<div class="'+cardCls+'">'+
      '<div class="skill-card-top">'+
        '<div class="skill-icon">'+esc(sk.ico||'◆')+'</div>'+
        '<div class="skill-meta">'+
          '<div class="skill-name">'+esc(nm)+'</div>'+
          '<div class="skill-tags">'+
            '<span class="skill-tag '+tagCls+'">'+esc(tagLabel)+'</span>'+
            (sk.req?'<span class="skill-tag" style="color:var(--tx3);border:1px solid var(--bg5);background:transparent">REQ: '+esc(sk.req.replace('_',' ').toUpperCase())+'</span>':'')+
          '</div>'+
        '</div>'+
        '<div style="text-align:right;flex-shrink:0">'+
          '<div class="skill-cost">'+esc(sk.c)+' SP</div>'+
        '</div>'+
      '</div>'+
      '<div class="skill-desc">'+esc(desc)+'</div>'+
      '<div class="skill-footer">'+
        '<div class="skill-level">'+
          (TH?'ระดับ':'Lv')+': '+levDisplay+
        '</div>'+
        btnH+
      '</div>'+
    '</div>';
  }).join('');

  return spH+
    '<div class="tct-row">'+filtersH+'</div>'+
    (cardsH||'<div class="empty-state">'+T('noskill')+'</div>');
}

