// ── UNLOCK OVERLAY ───────────────────────────────────────────────
function showUnlockOverlay(sk,newLv,spRem){
  var ov=g('kny-ov');var crd=g('kny-ovcrd');
  if(!ov||!crd)return;
  var lngTH=TH;
  function catLbl(cat,th){
    var en={all:'UNIVERSAL',slayer:'SLAYER',demon:'DEMON',hashira:'HASHIRA',upper_moon:'UPPER MOON'};
    var th_={all:'ทุกฝ่าย',slayer:'นักล่า',demon:'อสูร',hashira:'เสาหลัก',upper_moon:'Upper Moon'};
    return th?(th_[cat]||cat):(en[cat]||cat.toUpperCase());
  }
  function makePts(){
    var h='';var ang=[0,40,90,135,180,220,270,315];var dist=[55,68,60,72,58,65,63,70];
    for(var i=0;i<ang.length;i++){
      var r=ang[i]*Math.PI/180;
      var px=Math.round(Math.cos(r)*dist[i]);var py=Math.round(Math.sin(r)*dist[i]);
      h+='<div class="kny-ov-pt" style="--px:'+px+'px;--py:'+py+'px;--dur:'+(0.68+i*0.08).toFixed(2)+'s;--del:'+(i*0.055).toFixed(2)+'s;width:5px;height:5px"></div>';
    }
    return h;
  }
  function makeDots(max,cur){
    var h='';for(var i=1;i<=max;i++){h+='<div class="kny-ov-d'+(i<cur?' dn':i===cur?' cr':'')+'"></div>';}return h;
  }
  function render(th){
    var nm=th?sk.th:sk.en;var sub=th?sk.en:sk.th;
    var ef=th?(sk.tf||sk.ef):sk.ef;var desc=th?(sk.tD||sk.eD):sk.eD;
    var badge=newLv===1?'<span class="bdg-new">'+(th?'ใหม่':'NEW')+'</span>':'<span class="bdg-upg">'+(th?'อัพเกรด':'UPGRADE')+'</span>';
    var wm=(sk.jp||'').charAt(0)||'術';
    return '<div class="kny-ov-hd"><div class="kny-ov-ttl">'+(th?'ปลดล็อคสกิล':'SKILL ACQUIRED')+'</div><div class="kny-ov-x" id="kny-ovx">✕</div></div>'+
      '<div class="kny-ov-bd">'+
        '<div class="kny-ov-wm">'+esc(wm)+'</div>'+
        '<div class="kny-ov-iw"><div class="kny-ov-r"></div><div class="kny-ov-r2"></div><div class="kny-ov-r3"></div><div class="kny-ov-gl"></div><div class="kny-ov-ico">'+esc(sk.ico||'◆')+'</div>'+makePts()+'</div>'+
        '<div class="kny-ov-cat">'+esc(catLbl(sk.cat,th))+'</div>'+
        '<div class="kny-ov-nm">'+esc(nm)+badge+'</div>'+
        (sk.jp?'<div class="kny-ov-jp">'+esc(sk.jp)+'</div>':'')+
        (sub&&sub!==nm?'<div class="kny-ov-sub">'+esc(sub)+'</div>':'')+
        (sk.m>1?'<div class="kny-ov-lvls">'+makeDots(sk.m,newLv)+'<span class="kny-ov-lbl">'+(th?'ระดับ':'LV')+' '+newLv+' / '+sk.m+'</span></div>':'')+
        '<div class="kny-ov-ef"><div class="kny-ov-efico">'+esc(sk.ico||'◆')+'</div><div class="kny-ov-eftxt">'+esc(ef)+'</div></div>'+
        (desc?'<div class="kny-ov-desc">'+esc(desc)+'</div>':'')+
        '<div class="kny-ov-sep"></div>'+
        '<div class="kny-ov-ft">'+
          '<div class="kny-ov-sps">'+
            '<div class="kny-ov-spi"><span class="kny-ov-sl">'+(th?'ใช้ไป':'SP SPENT')+'</span><span class="kny-ov-sv sp">'+sk.c+'</span></div>'+
            '<div class="kny-ov-spi"><span class="kny-ov-sl">'+(th?'คงเหลือ':'SP LEFT')+'</span><span class="kny-ov-sv rm">'+spRem+'</span></div>'+
          '</div>'+
          '<div class="kny-ov-lng" id="kny-ovlng">'+(th?'EN':'TH')+'</div>'+
        '</div>'+
      '</div>'+
      '<div class="kny-ov-seal">'+(th?'鬼滅の刃 · ระบบสกิล · 術式習得':'鬼滅の刃 · SKILL SYSTEM · 術式習得')+'</div>';
  }
  crd.innerHTML=render(lngTH);
  ov.classList.add('on');
  ov.onclick=function(e){if(e.target===ov)ov.classList.remove('on');};
  crd.onclick=function(e){
    if(e.target.closest('#kny-ovx')){ov.classList.remove('on');return;}
    if(e.target.closest('#kny-ovlng')){lngTH=!lngTH;crd.innerHTML=render(lngTH);}
  };
}

// ── PANEL: CROW ──────────────────────────────────────────────────────────
function pCrow(){
  var cr=d.crow||{};
  var nm=cr.name||'—';
  var breed=cr.breed||'Jungle Crow';
  var ps=cr.personality||'—';
  var ap=cr.appearance||'—';
  var ot=cr.outfit||'—';
  var hg=cr.hunger||{cur:80,max:100};
  var md=(cr.mood||'neutral').toLowerCase();
  var moodMap={
    ecstatic:{ico:'🎉',fill:100,col:'#60d890'},
    great:{ico:'🎉',fill:100,col:'#60d890'},
    happy:{ico:'😊',fill:78,col:'#60c8a8'},
    good:{ico:'😊',fill:78,col:'#60c8a8'},
    neutral:{ico:'😐',fill:55,col:'#9090a0'},
    irritated:{ico:'😤',fill:30,col:'#d4a040'},
    bad:{ico:'😡',fill:12,col:'#d86050'},
    angry:{ico:'😡',fill:12,col:'#d86050'},
    hungry:{ico:'🍗',fill:8,col:'#d87840'}
  };
  var mo=moodMap[md]||moodMap.neutral;
  var moodLbl={ecstatic:T('moodGr'),great:T('moodGr'),happy:T('moodGo'),good:T('moodGo'),neutral:T('moodNe'),irritated:T('moodIr'),bad:T('moodBa'),angry:T('moodBa'),hungry:T('moodBa')}[md]||T('moodNe');
  var hgP=Math.max(0,Math.min(100,Math.round((parseFloat(hg.cur)||80)/(parseFloat(hg.max)||100)*100)));
  var moodPct=mo.fill;

  var infoRows=[[T('crowNm'),nm],[T('crowBr'),breed],[T('crowPs'),ps],[T('crowAp'),ap],[T('crowOt'),ot]];
  var infoH='<div class="igrid">';
  infoRows.forEach(function(r,i){
    infoH+='<div class="icard'+(i>=2?' full':'')+'"><div class="icard-l">'+esc(r[0])+'</div><div class="icard-v">'+esc(r[1])+'</div></div>';
  });
  infoH+='</div>';

  return '<div class="crow-portrait"><div class="crow-face">'+mo.ico+'</div><div class="crow-mood-nm">'+esc(moodLbl)+'</div></div>'+
    '<div class="kny-sec">'+T('crow')+'</div>'+
    infoH+
    '<div class="kny-sec mt">'+T('crowHg')+' · '+T('crowMd')+'</div>'+
    '<div class="bars">'+
      '<div class="crow-hbar-row"><div class="crow-hbar-lbl">'+T('crowHg')+'</div><div class="crow-hbar-track"><div class="crow-hbar-fill crow-hng-fill" style="width:'+hgP+'%"></div></div><div class="crow-hbar-val">'+esc(hg.cur)+'/'+esc(hg.max)+'</div></div>'+
      '<div class="crow-hbar-row"><div class="crow-hbar-lbl">'+T('crowMd')+'</div><div class="crow-hbar-track"><div class="crow-hbar-fill crow-moo-fill" style="width:'+moodPct+'%"></div></div><div class="crow-hbar-val" style="color:'+mo.col+'">'+esc(moodLbl)+'</div></div>'+
    '</div>';
}

// ── BUILD ────────────────────────────────────────────────────────
function build(){
  var faction=d.faction||'slayer';
  var acc=d.charColor||'#8B6FAE';
  var rgb=hexRgb(acc);
  var win=g('knywin');
  win.style.setProperty('--acc',acc);
  win.style.setProperty('--acc-rgb',rgb);
  win.style.setProperty('--abg','rgba('+rgb+',.12)');
  win.style.setProperty('--abd','rgba('+rgb+',.30)');
  win.style.setProperty('--bd','rgba('+rgb+',.25)');

  var sg=g('knysigil');if(sg)sg.innerHTML=sigil(faction,acc);

  var nm=g('knynm');if(nm)nm.textContent=d.name||'—';
  var rb=g('knyrb');
  if(rb){
    var ranks=faction==='slayer'?SLAYER_RANKS:DEMON_RANKS;
    var ri=getRankIdx(faction,d.rank||'');
    rb.textContent=(ranks[ri]?ranks[ri].k:'?')+' '+esc(d.rank||'—');
  }
  var ti=g('knytitle');if(ti)ti.textContent=TH?'ระบบสถานะ':'STATUS TRACKER';
  var lb=g('knylnbtn');if(lb)lb.textContent=TH?'TH':'EN';
  var ft=g('knyfoot');if(ft)ft.textContent=T('foot');

  // Header vitals
  var hv=g('knyhdvit');
  if(hv){
    var hp=d.hp||{cur:0,max:100};var st=d.stamina||{cur:0,max:100};
    hv.innerHTML=
      '<div class="hbar-row"><span class="hbar-lbl">HP</span><div class="hbar-track"><div class="hbar-fill hbar-hp" style="width:'+pct(hp.cur,hp.max)+'%"></div></div><span class="hbar-val">'+esc(hp.cur)+'/'+esc(hp.max)+'</span></div>'+
      (faction==='demon'?
        '<div class="hbar-row"><span class="hbar-lbl">気</span><div class="hbar-track"><div class="hbar-fill hbar-st" style="width:100%"></div></div><span class="hbar-val">∞</span></div>':
        '<div class="hbar-row"><span class="hbar-lbl">気</span><div class="hbar-track"><div class="hbar-fill hbar-st" style="width:'+pct(st.cur,st.max)+'%"></div></div><span class="hbar-val">'+esc(st.cur)+'/'+esc(st.max)+'</span></div>');
  }

  var defs=[
    ['status',TH?'สถานะ':'STATUS',pStatus],
    ['skill',TH?'ทักษะ':'SKILL',pSkills],
    ['tree',TH?'ต้นสกิล':'TREE',pTree],
    ['items',TH?'ของ':'ITEMS',pItems],
    ['gear',TH?'อุปกรณ์':'GEAR',pGear],
    ['fame',TH?'ชื่อเสียง':'FAME',pFame],
    ['crow',TH?'อีกา':'CROW',pCrow]
  ];
  var tabsH='',panesH='';
  defs.forEach(function(t,i){
    tabsH+='<div class="kny-tab'+(i===0?' active':'')+'" data-t="'+t[0]+'">'+esc(t[1])+'</div>';
    panesH+='<div class="kny-panel'+(i===0?' active':'')+'" data-p="'+t[0]+'">'+t[2]()+'</div>';
  });
  var tabs=g('knytabs');if(tabs)tabs.innerHTML=tabsH;
  var panes=g('knypanes');if(panes)panes.innerHTML=panesH;
}

build();

// ── EVENTS ───────────────────────────────────────────────────────
var head=g('knyhead');
if(head)head.addEventListener('click',function(){g('knywin').classList.toggle('closed')});

var lnbtn=g('knylnbtn');
if(lnbtn)lnbtn.addEventListener('click',function(e){e.stopPropagation();TH=!TH;build()});

var tabsEl=g('knytabs');
if(tabsEl)tabsEl.addEventListener('click',function(e){
  var tab=e.target.closest('.kny-tab');if(!tab)return;
  var t=tab.getAttribute('data-t');
  Array.prototype.forEach.call(tabsEl.querySelectorAll('.kny-tab'),function(x){x.classList.toggle('active',x===tab)});
  var panes=g('knypanes');
  if(panes)Array.prototype.forEach.call(panes.querySelectorAll('.kny-panel'),function(p){p.classList.toggle('active',p.getAttribute('data-p')===t)});
});

var panesEl=g('knypanes');
if(panesEl)panesEl.addEventListener('click',function(e){
  // Skill tree filter
  var tct=e.target.closest('.tct');
  if(tct){
    tctFilter=tct.getAttribute('data-cat')||'all';
    var panes=g('knypanes');
    if(panes){
      Array.prototype.forEach.call(panes.querySelectorAll('.kny-panel'),function(p){
        if(p.getAttribute('data-p')==='tree'){p.innerHTML=pTree()}
      });
      Array.prototype.forEach.call(panes.querySelectorAll('.tct'),function(x){x.classList.toggle('active',x.getAttribute('data-cat')===tctFilter)});
    }
    return;
  }
  // Skill unlock/upgrade button
  var skBtn=e.target.closest('.skill-btn[data-sk],.skill-mini-btn[data-sk]');
  if(skBtn&&!skBtn.disabled){
    var skId=skBtn.getAttribute('data-sk');
    var sk=null;for(var si=0;si<ST.length;si++){if(ST[si].id===skId){sk=ST[si];break}}
    if(!sk)return;
    var curSk=getUnlockedSkill(skId);
    var curLv=curSk?curSk.level:0;
    var newLv=curLv+1;
    var spRem=Math.max(0,(parseInt(d.skillPoints)||0)-sk.c);
    // Update local state immediately so tree re-renders correctly
    d.skillPoints=spRem;
    if(!d.unlockedSkills)d.unlockedSkills=[];
    var _found=false;
    for(var _i=0;_i<d.unlockedSkills.length;_i++){if(d.unlockedSkills[_i].id===skId){d.unlockedSkills[_i].level=newLv;_found=true;break;}}
    if(!_found)d.unlockedSkills.push({id:skId,level:newLv});
    // Re-render tree panel with updated d
    var _pn=g('knypanes');
    if(_pn)Array.prototype.forEach.call(_pn.querySelectorAll('.kny-panel'),function(p){if(p.getAttribute('data-p')==='tree')p.innerHTML=pTree();});
    showUnlockOverlay(sk,newLv,spRem);
    var msg='<'+'KNY_SKILL_UNLOCK>'+JSON.stringify({id:skId,action:'unlock',level:newLv})+'<'+'/KNY_SKILL_UNLOCK>';
    sendToChat(msg);
  }
});
})();
</script>
</body>
